// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';


export type KeyLightDiagramProps = Record<string, any>;

const KeyLightDiagram: React.FC<KeyLightDiagramProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 10,
  subjectColor = "#8b949e",
  lightColor = "#ffea00",
  lightIntensity = 0.8,
  lightPosition = "Left",
  fillLightColor = "#3498db",
  fillLightIntensity = 0.35,
  showLabels = true,
  gridOpacity = 0.4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safe background transparency logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // -- COORDINATE SYSTEM --
  // Subject in the upper-middle
  const Sx = width / 2;
  const Sy = height / 2 - 150;
  const R = 110;

  // Camera in the lower-middle
  const Cx = width / 2;
  const Cy = height / 2 + 350;

  // Key Light offset to 45 degrees
  const Lx = lightPosition === "Right" ? width / 2 + 450 : width / 2 - 450;
  const Ly = height / 2 + 100;

  // Fill Light offset to the opposite side (-45 degrees)
  const Fx = lightPosition === "Right" ? width / 2 - 450 : width / 2 + 450;
  const Fy = height / 2 + 100;

  // Props positioned at both top corners above the respective lights
  const Px1 = width / 2 - 450;
  const Px2 = width / 2 + 450;
  const Py = height / 2 - 350;

  // -- MATH FOR KEY LIGHT BEAM & ORIENTATION --
  const dx = Sx - Lx;
  const dy = Sy - Ly;
  const dist = Math.sqrt(dx * dx + dy * dy);

  const nx = dx / dist;
  const ny = dy / dist;

  const px = -ny;
  const py = nx;

  const lightRotRad = Math.atan2(dy, dx);
  const lightRotDeg = lightRotRad * (180 / Math.PI);

  const surfaceOffset = 20; 
  const lightHalfWidth = 60; 

  const le1_x = Lx + nx * surfaceOffset + px * lightHalfWidth;
  const le1_y = Ly + ny * surfaceOffset + py * lightHalfWidth;
  const le2_x = Lx + nx * surfaceOffset - px * lightHalfWidth;
  const le2_y = Ly + ny * surfaceOffset - py * lightHalfWidth;

  const se1_x = Sx + px * R;
  const se1_y = Sy + py * R;
  const se2_x = Sx - px * R;
  const se2_y = Sy - py * R;

  const beamPolygon = `${le1_x},${le1_y} ${le2_x},${le2_y} ${se2_x},${se2_y} ${se1_x},${se1_y}`;

  // -- MATH FOR FILL LIGHT BEAM & ORIENTATION --
  const fdx = Sx - Fx;
  const fdy = Sy - Fy;
  const fdist = Math.sqrt(fdx * fdx + fdy * fdy);

  const fnx = fdx / fdist;
  const fny = fdy / fdist;

  const fpx = -fny;
  const fpy = fnx;

  const fillRotRad = Math.atan2(fdy, fdx);
  const fillRotDeg = fillRotRad * (180 / Math.PI);

  const fe1_x = Fx + fnx * surfaceOffset + fpx * lightHalfWidth;
  const fe1_y = Fy + fny * surfaceOffset + fpy * lightHalfWidth;
  const fe2_x = Fx + fnx * surfaceOffset - fpx * lightHalfWidth;
  const fe2_y = Fy + fny * surfaceOffset - fpy * lightHalfWidth;

  const fse1_x = Sx + fpx * R;
  const fse1_y = Sy + fpy * R;
  const fse2_x = Sx - fpx * R;
  const fse2_y = Sy - fpy * R;

  const fillBeamPolygon = `${fe1_x},${fe1_y} ${fe2_x},${fe2_y} ${fse2_x},${fse2_y} ${fse1_x},${fse1_y}`;

  // -- ANIMATIONS (Sequential Order: Subject -> Camera -> Key Light -> Fill Light -> Props) --
  
  // 1. Subject
  const subjectScale = spring({ frame: frame - 10, fps, config: { damping: 14 } });
  
  // 2. Camera
  const camIntroSpring = spring({ frame: frame - 25, fps, config: { damping: 14 } });
  const camScale = interpolate(camIntroSpring, [0, 1], [0.8, 1]);
  const camOpacity = camIntroSpring;

  // 3. Key Light
  const lightIntroSpring = spring({ frame: frame - 40, fps, config: { damping: 14 } });
  const lightScale = interpolate(lightIntroSpring, [0, 1], [0.8, 1]);
  const lightOpacity = lightIntroSpring;

  // 4. Fill Light
  const fillIntroSpring = spring({ frame: frame - 55, fps, config: { damping: 14 } });
  const fillScale = interpolate(fillIntroSpring, [0, 1], [0.8, 1]);
  const fillOpacity = fillIntroSpring;

  // 5. Props
  const propIntroSpring = spring({ frame: frame - 70, fps, config: { damping: 14 } });
  const propScale = interpolate(propIntroSpring, [0, 1], [0.8, 1]);
  const propOpacity = propIntroSpring;

  const beamOpacity = interpolate(frame, [85, 105], [0, lightIntensity], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const overlayOpacity = interpolate(frame, [85, 105], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const fillBeamOpacity = interpolate(frame, [95, 115], [0, fillLightIntensity], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const fillOverlayOpacity = interpolate(frame, [95, 115], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const labelsOpacity = interpolate(frame, [115, 135], [0, showLabels ? 1 : 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Subtle floating effects
  const floatCamY = Math.sin(frame / 20) * 8;
  const floatProp1Y = Math.cos((frame + 15) / 25) * 8;
  const floatProp2Y = Math.cos((frame + 25) / 25) * 8;
  const floatLightY = Math.cos(frame / 25) * 10;
  const floatFillY = Math.cos((frame + 30) / 25) * 10;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Helvetica, Arial, sans-serif" }}>
      <svg width={width} height={height} style={{ transition: "none" }}>
        <defs>
          <pattern id="gridPattern" width="60" height="60" patternUnits="userSpaceOnUse">
            <path
              d="M 60 0 L 0 0 0 60"
              fill="none"
              stroke="rgba(255, 255, 255, 1)"
              strokeOpacity={gridOpacity * 0.05}
              strokeWidth="2"
            />
          </pattern>

          <linearGradient
            id="lightMaterial"
            gradientUnits="userSpaceOnUse"
            x1={Sx - nx * R}
            y1={Sy - ny * R}
            x2={Sx + nx * R}
            y2={Sy + ny * R}
          >
            <stop offset="0%" stopColor={lightColor} stopOpacity={0.6} />
            <stop offset="30%" stopColor={lightColor} stopOpacity={0.1} />
            <stop offset="55%" stopColor="#000000" stopOpacity={0.4} />
            <stop offset="100%" stopColor="#000000" stopOpacity={0.85} />
          </linearGradient>

          <linearGradient
            id="fillMaterial"
            gradientUnits="userSpaceOnUse"
            x1={Sx - fnx * R}
            y1={Sy - fny * R}
            x2={Sx + fnx * R}
            y2={Sy + fny * R}
          >
            <stop offset="0%" stopColor={fillLightColor} stopOpacity={1.2 * fillLightIntensity} />
            <stop offset="35%" stopColor={fillLightColor} stopOpacity={0.3 * fillLightIntensity} />
            <stop offset="60%" stopColor="#000000" stopOpacity={0} />
            <stop offset="100%" stopColor="#000000" stopOpacity={0} />
          </linearGradient>

          <linearGradient id="beamGradient" gradientUnits="userSpaceOnUse"
            x1={Lx} y1={Ly} x2={Sx} y2={Sy}
          >
            <stop offset="0%" stopColor={lightColor} stopOpacity={1} />
            <stop offset="100%" stopColor={lightColor} stopOpacity={0.1} />
          </linearGradient>

          <linearGradient id="fillBeamGradient" gradientUnits="userSpaceOnUse"
            x1={Fx} y1={Fy} x2={Sx} y2={Sy}
          >
            <stop offset="0%" stopColor={fillLightColor} stopOpacity={1} />
            <stop offset="100%" stopColor={fillLightColor} stopOpacity={0.1} />
          </linearGradient>
        </defs>

        {/* Grid Background */}
        <rect width="100%" height="100%" fill="url(#gridPattern)" />

        {/* Key Light Beam */}
        <polygon
          points={beamPolygon}
          fill="url(#beamGradient)"
          opacity={beamOpacity}
          style={{ transition: "none" }}
        />

        {/* Fill Light Beam */}
        <polygon
          points={fillBeamPolygon}
          fill="url(#fillBeamGradient)"
          opacity={fillBeamOpacity}
          style={{ transition: "none" }}
        />

        {/* 1. Subject */}
        <g transform={`translate(${Sx}, ${Sy}) scale(${subjectScale})`} style={{ transition: "none" }}>
          <g fill={subjectColor} stroke="rgba(255,255,255,0.1)" strokeWidth="4">
            <ellipse cx="0" cy="-15" rx="110" ry="55" />
            <circle cx="0" cy="20" r="45" />
          </g>
          <path d="M -12 60 Q 0 85 12 60 Z" fill={subjectColor} />

          <g opacity={overlayOpacity}>
            <ellipse cx="0" cy="-15" rx="110" ry="55" fill="url(#lightMaterial)" />
            <circle cx="0" cy="20" r="45" fill="url(#lightMaterial)" />
            <path d="M -12 60 Q 0 85 12 60 Z" fill="url(#lightMaterial)" />
          </g>

          <g opacity={fillOverlayOpacity} style={{ mixBlendMode: "screen", transition: "none" }}>
            <ellipse cx="0" cy="-15" rx="110" ry="55" fill="url(#fillMaterial)" />
            <circle cx="0" cy="20" r="45" fill="url(#fillMaterial)" />
            <path d="M -12 60 Q 0 85 12 60 Z" fill="url(#fillMaterial)" />
          </g>
        </g>

        {/* 2. Camera */}
        <g
          opacity={camOpacity}
          transform={`translate(${Cx}, ${Cy + floatCamY}) scale(${camScale})`}
          style={{ transition: "none" }}
        >
          <rect
            x="-60"
            y="-30"
            width="120"
            height="70"
            rx="8"
            fill="#2d333b"
            stroke="rgba(255,255,255,0.2)"
            strokeWidth="4"
          />
          <path
            d="M -30 -30 L -40 -70 L 40 -70 L 30 -30 Z"
            fill="#22272e"
            stroke="rgba(255,255,255,0.2)"
            strokeWidth="4"
          />
          <circle cx="0" cy="-50" r="15" fill="#111" />
          <rect x="30" y="-40" width="16" height="10" rx="3" fill="#d73a49" />
        </g>

        {/* 3. Key Light */}
        <g
          opacity={lightOpacity}
          transform={`translate(${Lx}, ${Ly + floatLightY}) scale(${lightScale})`}
          style={{ transition: "none" }}
        >
          <g transform={`rotate(${lightRotDeg})`}>
            <rect x="-60" y="-30" width="40" height="60" rx="6" fill="#1a1a1a" stroke="#333" strokeWidth="2" />
            <path d="M -20 -30 L 20 -60 L 20 60 L -20 30 Z" fill="#2d333b" stroke="#444" strokeWidth="2" />
            <line
              x1="20"
              y1="-58"
              x2="20"
              y2="58"
              stroke={lightColor}
              strokeWidth="6"
              strokeLinecap="round"
              opacity={0.3 + (beamOpacity * 0.7)}
            />
          </g>
        </g>

        {/* 4. Fill Light */}
        <g
          opacity={fillOpacity}
          transform={`translate(${Fx}, ${Fy + floatFillY}) scale(${fillScale})`}
          style={{ transition: "none" }}
        >
          <g transform={`rotate(${fillRotDeg})`}>
            <rect x="-60" y="-30" width="40" height="60" rx="6" fill="#1a1a1a" stroke="#333" strokeWidth="2" />
            <path d="M -20 -30 L 20 -60 L 20 60 L -20 30 Z" fill="#2d333b" stroke="#444" strokeWidth="2" />
            <line
              x1="20"
              y1="-58"
              x2="20"
              y2="58"
              stroke={fillLightColor}
              strokeWidth="6"
              strokeLinecap="round"
              opacity={0.3 + ((fillBeamOpacity / fillLightIntensity) * 0.7)}
            />
          </g>
        </g>

        {/* 5. Props (Left & Right) */}
        <g
          opacity={propOpacity}
          transform={`translate(${Px1}, ${Py + floatProp1Y}) scale(${propScale})`}
          style={{ transition: "none" }}
        >
          <rect
            x="-55"
            y="-55"
            width="110"
            height="110"
            rx="12"
            fill="#2d333b"
            stroke="rgba(255,255,255,0.2)"
            strokeWidth="4"
          />
          <text
            y="8"
            fill="rgba(255, 255, 255, 0.8)"
            fontSize="24"
            fontWeight="bold"
            textAnchor="middle"
            letterSpacing="0.05em"
            style={{ transition: "none" }}
          >
            PROP
          </text>
        </g>
        <g
          opacity={propOpacity}
          transform={`translate(${Px2}, ${Py + floatProp2Y}) scale(${propScale})`}
          style={{ transition: "none" }}
        >
          <rect
            x="-55"
            y="-55"
            width="110"
            height="110"
            rx="12"
            fill="#2d333b"
            stroke="rgba(255,255,255,0.2)"
            strokeWidth="4"
          />
          <text
            y="8"
            fill="rgba(255, 255, 255, 0.8)"
            fontSize="24"
            fontWeight="bold"
            textAnchor="middle"
            letterSpacing="0.05em"
            style={{ transition: "none" }}
          >
            PROP
          </text>
        </g>

        {/* -- LABELS -- */}
        <g
          opacity={labelsOpacity}
          fill="rgba(255, 255, 255, 0.8)"
          fontSize="24"
          fontWeight="bold"
          textAnchor="middle"
          letterSpacing="0.05em"
          style={{ transition: "none" }}
        >
          <text x={Sx} y={Sy - R - 35}>SUBJECT</text>
          <text x={Cx} y={Cy + 85 + floatCamY}>CAMERA</text>
          <text x={Lx} y={Ly + 105 + floatLightY}>KEY LIGHT</text>
          <text x={Fx} y={Fy + 105 + floatFillY}>FILL LIGHT</text>
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default KeyLightDiagram;